import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with register blocking
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 4
#define PADDING 1

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE + PADDING];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + PADDING];

    int base_row = blockIdx.y * TILE_SIZE + threadIdx.y * BLOCK_SIZE;
    int base_col = blockIdx.x * TILE_SIZE + threadIdx.x * BLOCK_SIZE;

    float sum[BLOCK_SIZE][BLOCK_SIZE] = {0.0f};

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tiles into shared memory with coalesced access
        for (int i = 0; i < BLOCK_SIZE; i++) {
            for (int j = 0; j < BLOCK_SIZE; j++) {
                int row = base_row + i;
                int col = tile * TILE_SIZE + threadIdx.x * BLOCK_SIZE + j;

                if (row < N && col < N) {
                    As[threadIdx.y * BLOCK_SIZE + i][threadIdx.x * BLOCK_SIZE + j] = A[row * N + col];
                } else {
                    As[threadIdx.y * BLOCK_SIZE + i][threadIdx.x * BLOCK_SIZE + j] = 0.0f;
                }

                row = tile * TILE_SIZE + threadIdx.y * BLOCK_SIZE + i;
                col = base_col + j;

                if (row < N && col < N) {
                    Bs[threadIdx.y * BLOCK_SIZE + i][threadIdx.x * BLOCK_SIZE + j] = B[row * N + col];
                } else {
                    Bs[threadIdx.y * BLOCK_SIZE + i][threadIdx.x * BLOCK_SIZE + j] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial sums using register blocking
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            #pragma unroll
            for (int i = 0; i < BLOCK_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    sum[i][j] += As[threadIdx.y * BLOCK_SIZE + i][k] * Bs[k][threadIdx.x * BLOCK_SIZE + j];
                }
            }
        }

        __syncthreads();
    }

    // Write results back to global memory
    for (int i = 0; i < BLOCK_SIZE; i++) {
        for (int j = 0; j < BLOCK_SIZE; j++) {
            int row = base_row + i;
            int col = base_col + j;
            if (row < N && col < N) {
                C[row * N + col] = sum[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int THREADS_PER_BLOCK = TILE_SIZE / BLOCK_SIZE;
    dim3 block(THREADS_PER_BLOCK, THREADS_PER_BLOCK);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

